    pub const EXTERNAL: Self = Self(0x0000_0000_0000_0004);
    pub const UNKNOWN_REMAINDER: Self = Self(0x0000_0000_0000_0008);
    pub const PYTHON_PROFILE: Self = Self(0x0000_0001_0000_0000);
